package com.vandorlabs.neoforge.gear;

import com.vandorlabs.neoforge.world.NativeLoadedTileIndex;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.*;
import net.minecraft.world.phys.shapes.*;

/** Global moving geometry reaches outside source cells; every query rechecks installed loaded identity. */
public final class NativeGearTargets {
    private static final NativeLoadedTileIndex<NativeGearEntity> ROOTS=new NativeLoadedTileIndex<>(NativeGearEntity.class);
    private static long indexPublications;
    public static synchronized long indexPublications(){return indexPublications;}
    private static final ThreadLocal<NativeGearEntity> EXCLUDED=new ThreadLocal<>();
    private static final ThreadLocal<Set<BlockPos>> PREFLIGHT=new ThreadLocal<>();
    static <T> T excluding(NativeGearEntity owner,Set<BlockPos> sources,java.util.function.Supplier<T> action){var previous=EXCLUDED.get();var cells=PREFLIGHT.get();EXCLUDED.set(owner);PREFLIGHT.set(sources);try{return action.get();}finally{if(previous==null)EXCLUDED.remove();else EXCLUDED.set(previous);if(cells==null)PREFLIGHT.remove();else PREFLIGHT.set(cells);}}
    private static final class Reaches {final Map<NativeGearEntity,Double> owners=new IdentityHashMap<>();double maximum;}
    private static final Map<Level,Reaches> REACHES=new IdentityHashMap<>();
    private static final Map<NativeGearEntity,Level> REGISTERED=new IdentityHashMap<>();
    public static synchronized void add(NativeGearEntity owner){if(!com.vandorlabs.neoforge.fluid.NativeFluidWorld.open(owner.getLevel())){remove(owner);return;}if(REGISTERED.get(owner)==owner.getLevel()){changed(owner);return;}remove(owner);ROOTS.add(owner);indexPublications++;if(owner.getLevel()!=null){REGISTERED.put(owner,owner.getLevel());changed(owner);}}
    public static synchronized void remove(NativeGearEntity owner){ROOTS.remove(owner);var level=REGISTERED.remove(owner);var entries=REACHES.get(level);if(entries!=null){Double previous=entries.owners.remove(owner);if(entries.owners.isEmpty())REACHES.remove(level);else if(previous!=null&&previous==entries.maximum)entries.maximum=entries.owners.values().stream().mapToDouble(Double::doubleValue).max().orElse(0);}}
    public static synchronized void changed(NativeGearEntity owner){var level=owner.getLevel();if(level==null||owner.isRemoved())return;if(REGISTERED.get(owner)!=level){add(owner);return;}var entries=REACHES.computeIfAbsent(level,ignored->new Reaches());double radius=owner.controller()&&!owner.inert()?owner.geometryReach():0;Double previous=entries.owners.get(owner);if(previous!=null&&previous==radius)return;entries.owners.put(owner,radius);if(radius>=entries.maximum)entries.maximum=radius;else if(previous!=null&&previous==entries.maximum)entries.maximum=entries.owners.values().stream().mapToDouble(Double::doubleValue).max().orElse(0);}
    public static synchronized double searchReach(Level world){var entries=REACHES.get(world);return entries==null?0:entries.maximum;}
    /** Loaded installed roots whose conservative moving footprint can meet the supplied world bounds. */
    public static synchronized void visit(Level world,AABB bounds,java.util.function.Consumer<NativeGearEntity> visitor){double reach=searchReach(world);if(reach<=0||!ROOTS.hasNearbyBuckets(world,bounds,reach))return;ROOTS.visit(world,bounds.inflate(reach),owner->!owner.inert()&&owner.controller(),visitor);}
    @net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs") public static final class Lifecycle {@net.neoforged.bus.api.SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload event){if(event.getLevel() instanceof Level level)synchronized(NativeGearTargets.class){REACHES.remove(level);REGISTERED.entrySet().removeIf(entry->entry.getValue()==level);}}}
    public static boolean excluded(NativeGearEntity member){var owner=EXCLUDED.get();return owner!=null&&(owner==member||owner.getBlockPos().equals(member.owner())||owner.getLevel()==member.getLevel()&&PREFLIGHT.get()!=null&&PREFLIGHT.get().contains(member.getBlockPos()));}
    public static synchronized Iterable<VoxelShape> blockCollisions(Level world,net.minecraft.world.entity.Entity actor,AABB query,Iterable<VoxelShape> vanilla){if(!NativeGearBindings.enabled())return vanilla;double reach=searchReach(world);if(reach<=0||!ROOTS.hasNearbyBuckets(world,query,reach))return vanilla;List<VoxelShape> extra=new ArrayList<>();ROOTS.visit(world,query.inflate(reach),owner->owner!=EXCLUDED.get()&&!owner.inert()&&owner.controller(),owner->{for(var original:owner.collisionBoxes()){var box=com.vandorlabs.neoforge.ramp.NativeRampRiders.supportCollision(original,actor,owner.progress()>0&&owner.progress()<1);if(box!=null&&box.intersects(query))extra.add(Shapes.create(box));}});if(extra.isEmpty())return vanilla;return ()->{var first=vanilla.iterator();var second=extra.iterator();return new Iterator<>(){public boolean hasNext(){return first.hasNext()||second.hasNext();}public VoxelShape next(){return first.hasNext()?first.next():second.next();}};};}
    private static boolean loaded(Level world,AABB bounds){int x0=((int)Math.floor(bounds.minX))>>4,x1=((int)Math.floor(bounds.maxX))>>4,z0=((int)Math.floor(bounds.minZ))>>4,z1=((int)Math.floor(bounds.maxZ))>>4;if((long)(x1-x0+1)*(z1-z0+1)>256)return false;for(int x=x0;x<=x1;x++)for(int z=z0;z<=z1;z++)if(world.getChunkSource().getChunkNow(x,z)==null)return false;return bounds.minY>=world.getMinBuildHeight()&&bounds.maxY<=world.getMaxBuildHeight();}
    public static boolean clear(NativeGearEntity owner,double before,double after){var world=owner.getLevel();if(world==null||!owner.authority()||owner.assembly()==null)return false;return clear(owner,before,after,NativeGearGeometry.boxes(owner,before),NativeGearGeometry.boxes(owner,after));}
    static boolean clear(NativeGearEntity owner,double before,double after,List<AABB> a,List<AABB> b){var world=owner.getLevel();if(world==null||!owner.authority()||owner.assembly()==null||a.size()!=b.size())return false;NativeGearEntity prior=EXCLUDED.get();EXCLUDED.set(owner);try{for(int i=0;i<a.size();i++){if(a.get(i).equals(b.get(i)))continue;var sweep=NativeGearGeometry.swept(owner,a.get(i),b.get(i),before,after);if(sweep.getXsize()<=0||sweep.getYsize()<=0||sweep.getZsize()<=0)continue;if(!loaded(world,sweep))return false;for(var collision:world.getBlockCollisions(null,sweep))if(Shapes.joinIsNotEmpty(Shapes.create(sweep),collision,BooleanOp.AND))return false;}return true;}finally{if(prior==null)EXCLUDED.remove();else EXCLUDED.set(prior);}}
    public static boolean clearPath(NativeGearEntity owner,double from,double to){double prior=from;int steps=Math.max(1,(int)Math.ceil(Math.abs(to-from)*NativeGearEntity.DURATION));for(int i=1;i<=steps;i++){double next=from+(to-from)*i/steps;if(!clear(owner,prior,next))return false;prior=next;}return true;}
    public static BlockHitResult trace(NativeGearEntity owner,Vec3 start,Vec3 end){BlockHitResult best=null;double distance=Double.POSITIVE_INFINITY;for(var box:owner.collisionBoxes()){var hit=Shapes.create(box).clip(start,end,BlockPos.ZERO);if(hit!=null&&start.distanceToSqr(hit.getLocation())<distance){distance=start.distanceToSqr(hit.getLocation());best=new BlockHitResult(hit.getLocation(),hit.getDirection(),owner.getBlockPos(),false);}}return best;}
    private NativeGearTargets(){}
}
